steps.script:
var pts = [Vector2(41.0, 35.0), Vector2(42.6, 35.0), Vector2(41.0, 36.6), Vector2(42.6, 36.6), Vector2(41.8, 38.2)]
var ms = GameState.get_unit("U_NOBZ_A").models
for i in range(ms.size()):
	ms[i]["position"] = {"x": pts[i].x * 40.0, "y": pts[i].y * 40.0}
var ph = PhaseManager.get_current_phase_instance()
ph.game_state_snapshot = GameState.create_snapshot()
ph._compute_engagement_flags()
tree.root.get_node("Main")._recreate_unit_visuals()
return RulesEngine.is_unit_engaged("U_NOBZ_A", GameState.state)

var dl = tree.root.get_node("StratagemDialog")
var sc = dl.get_node("Content/StratScroll")
var view = sc.get_global_rect()
var n = 0
var shown = 0
for card in sc.get_node("StratList").get_children():
	var b = card.get_node_or_null("Buttons")
	if b == null:
		continue
	for btn in b.get_children():
		if btn is Button and btn.visible:
			n += 1
			var r = btn.get_global_rect()
			if r.position.y >= view.position.y - 0.5 and r.end.y <= view.end.y + 0.5:
				shown += 1
var vp = tree.root.get_visible_rect().size
var on_screen = dl.position.y >= 0 and dl.position.y + dl.size.y <= vp.y
return "%d/%d on_screen=%s" % [shown, n, str(on_screen)]

var log = PhaseManager.get_current_phase_instance().dice_log
for i in range(log.size() - 1, -1, -1):
	if str(log[i].get("context", "")) == "to_wound":
		return int(log[i].get("wound_modifier_net", 0))
return 99

var labels = tree.current_scene.game_log_panel.last_combat_card_dice_labels()
for l in labels:
	if l.begins_with("Wound (") and l.contains("-1 to wound"):
		return true
return str(labels)

var log = PhaseManager.get_current_phase_instance().dice_log
for i in range(log.size() - 1, -1, -1):
	if str(log[i].get("context", "")) == "to_wound":
		var drv = tree.current_scene.shooting_controller.dice_roll_visual
		drv.show_dice_roll(log[i])
		return drv._context_label.ends_with(", -1 to wound)")
return false

var found := false
var q: Array = [tree.root]
while not q.is_empty():
	var c = q.pop_front()
	if (c is Label or c is Button or c is RichTextLabel) and c.is_visible_in_tree() and str(c.text).to_upper().contains("SENTINEL STORM"):
		found = true
		break
	q.append_array(c.get_children())
return found
